"""Postprocess scalar slew-rate measurements generated by ngspice."""

OUTPUTS = (
    "sr_pos_vus",
    "sr_neg_vus",
    "sr_rise_10_90_vus",
    "sr_fall_90_10_vus",
    "tr_10_90_s",
    "tf_90_10_s",
)


def postprocess(results, conditions):
    output = {}

    for name in OUTPUTS:
        raw_name = f"raw_{name}"

        if raw_name not in results:
            raise ValueError(
                f"Missing slew-rate measurement: {raw_name}. "
                f"Available: {list(results)}"
            )

        values = results[raw_name]

        if not values:
            raise ValueError(f"Empty slew-rate measurement: {raw_name}")

        output[name] = [float(value) for value in values]

    return output
